                // Check for duplicates in the merged list
                if (current.next == null || current.next.val != p1.val) {
                    current.next = p1;
                    current = current.next;
                }
                p1 = p1.next;
            } else if (p1.val > p2.val) {
                // Check for duplicates in the merged list
                if (current.next == null || current.next.val != p2.val) {
                    current.next = p2;
                    current = current.next;
                }
                p2 = p2.next;
            } else {
                // Values are equal, check for duplicates in the merged list
                if (current.next == null || current.next.val != p1.val) {
                    current.next = p1;
                    current = current.next;
                }
                // Move both pointers since values are equal
                p1 = p1.next;
                p2 = p2.next;
            }
        }

        // Append the remaining elements of the non-null list
        while (p1 != null) {
            if (current.next == null || current.next.val != p1.val) {
                current.next = p1;
                current = current.next;
            }
            p1 = p1.next;
        }

        while (p2 != null) {
            if (current.next == null || current.next.val != p2.val) {
                current.next = p2;
                current = current.next;
            }
            p2 = p2.next;
        }

        // Return the merged list, starting from the dummy's next
        return dummy.next;
    }

    /**
     * Main method to test the mergeLists function.
     */
    public static void main(String[] args) {
        // Example usage
        ListNode list1 = new ListNode(1);
        list1.next = new ListNode(2);
        list1.next.next = new ListNode(3);

        ListNode list2 = new ListNode(2);
        list2.next = new ListNode(3);
        list2.next.next = new ListNode(4);

        ListNode mergedList = mergeLists(list1, list2);

        // Print the merged list
        while (mergedList != null) {
            System.out.print(mergedList.val + " ");
            mergedList = mergedList.next;
        }
    }
}
